CREATE OR REPLACE FUNCTION public.comprar_entradas(p_evento_id text, p_lineas jsonb, p_correo_destino text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  -- ─── ZONA EDITABLE: reglas de negocio ──────────────────────────
  c_tasa_cargos    constant numeric := 0.07; -- 7 % (mantener igual que lib/compras/calculo.ts)
  c_max_lineas     constant int     := 10;   -- tipos de ticket distintos por compra
  c_max_por_linea  constant int     := 10;   -- entradas por tipo en una compra
  -- ───────────────────────────────────────────────────────────────

  v_uid              uuid := auth.uid();
  v_correo           text := lower(btrim(coalesce(p_correo_destino, '')));
  v_destino_id       uuid;
  v_destino_nombre   text;
  v_evento_id        public.eventos.id%type;
  v_compra_id        public.compras.id%type;
  v_linea            record;
  v_ticket           record;
  v_ya_comprados     int;
  v_subtotal         numeric := 0;
  v_cargos           numeric;
  v_total            numeric;
  v_n_entradas       int := 0;
  v_i                int;
begin
  -- 1) Debe haber sesión. comprador_id SIEMPRE es auth.uid(), nunca un parámetro.
  if v_uid is null then
    raise exception 'NO_AUTH';
  end if;

  -- 2) El evento debe estar publicado y no haber pasado.
  select e.id into v_evento_id
  from public.eventos e
  where e.id::text = p_evento_id
    and e.estado = 'publicado'
    and e.fecha_evento > now();
  if not found then
    raise exception 'EVENTO_NO_DISPONIBLE';
  end if;

  -- 3) Validar las líneas (el JSON viene del navegador: no se confía).
  if p_lineas is null
     or jsonb_typeof(p_lineas) <> 'array'
     or jsonb_array_length(p_lineas) not between 1 and c_max_lineas then
    raise exception 'LINEAS_INVALIDAS';
  end if;

  if exists (
    select 1
    from jsonb_array_elements(p_lineas) l
    where jsonb_typeof(l -> 'tipo_ticket_id') is distinct from 'string'
       or jsonb_typeof(l -> 'cantidad') is distinct from 'number'
       or case when (l ->> 'cantidad') ~ '^[0-9]{1,3}$'
               then (l ->> 'cantidad')::int
               else 0
          end not between 1 and c_max_por_linea
  ) then
    raise exception 'LINEAS_INVALIDAS';
  end if;

  if (select count(distinct l ->> 'tipo_ticket_id') from jsonb_array_elements(p_lineas) l)
     <> jsonb_array_length(p_lineas) then
    raise exception 'LINEAS_INVALIDAS'; -- mismo tipo repetido
  end if;

  -- 4) Destinatario: para mí, o buscar su UUID por correo.
  if v_correo = '' then
    v_destino_id := v_uid;
  else
    if length(v_correo) > 254 or v_correo !~ '^[^@\s]+@[^@\s]+$' then
      raise exception 'CORREO_INVALIDO';
    end if;

    select u.id, u.nombre into v_destino_id, v_destino_nombre
    from public.usuarios u
    where lower(u.correo) = v_correo
    limit 1;

    if not found then
      raise exception 'DESTINATARIO_NO_REGISTRADO';
    end if;
    if v_destino_id = v_uid then
      raise exception 'DESTINATARIO_ES_COMPRADOR';
    end if;
  end if;

  -- 5) Crear la compra en "pendiente" (los totales se fijan al final).
  insert into public.compras (comprador_id, subtotal, cargos_servicio, total, estado_pago)
  values (v_uid, 0, 0, 0, 'pendiente')
  returning id into v_compra_id;

  -- 6) Por cada tipo de ticket: descuento ATÓMICO de cupo + una fila por entrada.
  --    Se recorren ordenadas por id para que dos compras simultáneas bloqueen
  --    las filas en el mismo orden (evita deadlocks).
  for v_linea in
    select l ->> 'tipo_ticket_id' as tipo_id,
           (l ->> 'cantidad')::int as cantidad
    from jsonb_array_elements(p_lineas) l
    order by 1
  loop
    -- UPDATE ... WHERE cantidad_disponible >= cantidad: si dos compras compiten
    -- por el último cupo, la segunda espera el lock y NO encuentra fila.
    update public.tipos_ticket t
       set cantidad_disponible = t.cantidad_disponible - v_linea.cantidad
     where t.id::text = v_linea.tipo_id
       and t.evento_id = v_evento_id
       and t.cantidad_disponible >= v_linea.cantidad
    returning t.id, t.nombre, t.precio, t.limite_por_usuario
      into v_ticket;

    if not found then
      select t.nombre into v_ticket
      from public.tipos_ticket t
      where t.id::text = v_linea.tipo_id and t.evento_id = v_evento_id;

      if found then
        raise exception 'SIN_CUPO' using detail = v_ticket.nombre;
      end if;
      raise exception 'TIPO_INVALIDO';
    end if;

    -- Límite por usuario (cuenta lo que ya compró; ya tenemos el lock de la fila,
    -- así que dos compras del mismo usuario no pueden saltarse el límite).
    if v_ticket.limite_por_usuario is not null then
      select count(*) into v_ya_comprados
      from public.entradas e
      join public.compras c on c.id = e.compra_id
      where c.comprador_id = v_uid
        and e.tipo_ticket_id = v_ticket.id
        and e.estado <> 'anulada'
        and c.estado_pago <> 'fallido';

      if v_ya_comprados + v_linea.cantidad > v_ticket.limite_por_usuario then
        raise exception 'LIMITE_EXCEDIDO'
          using detail = v_ticket.nombre,
                hint   = greatest(v_ticket.limite_por_usuario - v_ya_comprados, 0)::text;
      end if;
    end if;

    -- Una fila en "entradas" por cada ticket, con su propio codigo_qr único
    -- (122 bits aleatorios: no adivinable; el índice único es la red de seguridad).
    for v_i in 1..v_linea.cantidad loop
      insert into public.entradas (compra_id, tipo_ticket_id, usuario_destino_id, codigo_qr, estado)
      values (
        v_compra_id,
        v_ticket.id,
        v_destino_id,
        'QP-' || upper(replace(gen_random_uuid()::text, '-', '')),
        'activa'
      );
    end loop;

    -- El precio sale de la BD, jamás del navegador.
    v_subtotal   := v_subtotal + v_ticket.precio * v_linea.cantidad;
    v_n_entradas := v_n_entradas + v_linea.cantidad;
  end loop;

  -- 7) Totales + PAGO SIMULADO.
  --    ▼▼▼ Cuando exista la pasarela real, reemplaza este bloque: aquí se
  --    cobraría y, según el resultado, 'confirmado' o 'fallido'. ▼▼▼
  v_cargos := round(v_subtotal * c_tasa_cargos, 2);
  v_total  := v_subtotal + v_cargos;

  update public.compras
     set subtotal        = v_subtotal,
         cargos_servicio = v_cargos,
         total           = v_total,
         estado_pago     = 'confirmado'
   where id = v_compra_id;

  return jsonb_build_object(
    'compra_id',       v_compra_id,
    'entradas',        v_n_entradas,
    'subtotal',        v_subtotal,
    'cargos_servicio', v_cargos,
    'total',           v_total,
    'destinatario',    v_destino_nombre  -- null si compró para sí mismo
  );
end;
$function$

CREATE OR REPLACE FUNCTION public.comprar_entradas_prueba(p_evento_id text, p_lineas jsonb, p_correo_destino text, p_solicitud_id uuid, p_resultado text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_uid uuid := auth.uid(); v_seleccion jsonb; v_anterior public.intentos_compra_prueba%rowtype; v_respuesta jsonb;
begin
  if v_uid is null then raise exception 'NO_AUTH'; end if;
  if p_solicitud_id is null or p_resultado is null or p_resultado not in ('aprobado','rechazado','vencido') then raise exception 'PRUEBA_INVALIDA'; end if;
  if p_lineas is null or jsonb_typeof(p_lineas)<>'array' then raise exception 'LINEAS_INVALIDAS'; end if;
  v_seleccion := jsonb_build_object('evento',p_evento_id,'lineas',p_lineas,
    'destino',lower(btrim(coalesce(p_correo_destino,''))),'resultado',p_resultado);
  -- Serializa reintentos de una misma solicitud, sin mezclar usuarios.
  perform pg_advisory_xact_lock(hashtextextended(v_uid::text || ':' || p_solicitud_id::text,0));
  select * into v_anterior from public.intentos_compra_prueba where usuario_id=v_uid and solicitud_id=p_solicitud_id;
  if found then
    if v_anterior.seleccion<>v_seleccion then raise exception 'SOLICITUD_REUTILIZADA'; end if;
    return v_anterior.respuesta;
  end if;
  if p_resultado='aprobado' then
    v_respuesta := public.comprar_entradas(p_evento_id,p_lineas,p_correo_destino) || jsonb_build_object('modo','prueba');
  else
    v_respuesta := jsonb_build_object('modo','prueba','error',case when p_resultado='rechazado' then 'PAGO_PRUEBA_RECHAZADO' else 'PAGO_PRUEBA_VENCIDO' end);
  end if;
  insert into public.intentos_compra_prueba(usuario_id,solicitud_id,seleccion,respuesta)
    values(v_uid,p_solicitud_id,v_seleccion,v_respuesta);
  return v_respuesta;
end;
$function$

CREATE OR REPLACE FUNCTION public.consultar_lote_qr(p_lote integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_lote public.lotes_qr_fisico%rowtype; v_result jsonb;
begin
  if not public.qpass_autorizado_evento(null,array[]::text[]) then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  select * into v_lote from public.lotes_qr_fisico where id=p_lote;
  if not found then raise exception 'LOTE_NO_ENCONTRADO'; end if;
  select jsonb_build_object('id',v_lote.id,'eventoId',v_lote.evento_id,'cantidad',v_lote.cantidad,
    'evento',e.titulo,'codigos',(select coalesce(jsonb_agg(jsonb_build_object(
      'codigo',v.codigo_qr,'vinculado',v.entrada_id is not null) order by v.id),'[]'::jsonb)
      from public.vinculos_qr_fisico v where v.lote_id=p_lote)) into v_result
    from public.eventos e where e.id=v_lote.evento_id;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.corregir_acceso(p_id integer, p_version integer, p_resultado text, p_observacion text, p_motivo text, p_eliminar boolean DEFAULT false)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_reg public.registros_acceso%rowtype; v_after public.registros_acceso%rowtype; v_evento integer; v_entrada public.entradas%rowtype;
begin
  select a.* into v_reg from public.registros_acceso a where id=p_id;
  select t.evento_id into v_evento from public.entradas en join public.tipos_ticket t on t.id=en.tipo_ticket_id where en.id=v_reg.entrada_id;
  if not found or not public.qpass_autorizado_evento(v_evento,array['supervisor']) or
    (v_reg.supervisor_id<>auth.uid() and not public.qpass_autorizado_evento(null,array[]::text[])) then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  if p_resultado is null or p_resultado not in ('permitido','denegado') or p_eliminar is null or length(btrim(coalesce(p_motivo,''))) not between 5 and 500 or length(coalesce(p_observacion,''))>1000 then raise exception 'DATOS_INVALIDOS'; end if;
  perform c.id from public.compras c join public.entradas en on en.compra_id=c.id where en.id=v_reg.entrada_id for update of c;
  perform t.id from public.tipos_ticket t join public.entradas en on en.tipo_ticket_id=t.id where en.id=v_reg.entrada_id for update of t;
  select * into v_entrada from public.entradas where id=v_reg.entrada_id for update;
  select * into v_reg from public.registros_acceso where id=p_id for update;
  if v_reg.version is distinct from p_version or v_reg.eliminado then raise exception 'REGISTRO_CAMBIO'; end if;
  if not p_eliminar and p_resultado='permitido' and v_reg.resultado='denegado' then
    if v_entrada.estado<>'activa' or not exists(select 1 from public.compras where id=v_entrada.compra_id and estado_pago='confirmado')
       or not exists(select 1 from public.usuarios where id=v_entrada.usuario_destino_id and activo) then raise exception 'ENTRADA_NO_APTA'; end if;
    update public.entradas set estado='usada' where id=v_entrada.id;
  end if;
  -- Una corrección o borrado NO devuelve el derecho de ingreso de una entrada usada.
  update public.registros_acceso set resultado=p_resultado::public.resultado_acceso,observacion=coalesce(p_observacion,''),eliminado=p_eliminar,version=version+1 where id=p_id returning * into v_after;
  insert into public.auditoria_accesos(registro_id,actor_id,motivo,antes,despues) values(p_id,auth.uid(),btrim(p_motivo),to_jsonb(v_reg),to_jsonb(v_after));
  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.eliminar_evento_sin_ventas(p_evento_id integer)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_borrados integer;
begin
  if public.evento_tiene_entradas(p_evento_id) then
    raise exception 'CON_VENTAS';
  end if;

  delete from public.tipos_ticket where evento_id = p_evento_id;
  delete from public.eventos where id = p_evento_id;
  get diagnostics v_borrados = row_count;

  if v_borrados = 0 then
    raise exception 'NO_ENCONTRADO'; -- no existe o no es tuyo (y revierte el borrado de tickets)
  end if;
end;
$function$

CREATE OR REPLACE FUNCTION public.estadisticas_evento(p_evento_id integer)
 RETURNS TABLE(usuarios bigint, entradas_vendidas bigint, ingreso_entradas numeric, ingreso_servicios numeric, ingreso_total numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_entradas  bigint;
  v_usuarios  bigint;
  v_subtotal  numeric;
  v_servicios numeric;
begin
  if not exists (
    select 1 from public.eventos e
    where e.id = p_evento_id
      and (e.organizador_id = (select auth.uid()) or public.es_admin())
  ) then
    raise exception 'Sin permisos para ver las estadísticas de este evento.' using errcode = '42501';
  end if;

  select count(en.id), count(distinct en.usuario_destino_id), coalesce(sum(t.precio), 0)
    into v_entradas, v_usuarios, v_subtotal
  from public.entradas en
  join public.tipos_ticket t on t.id = en.tipo_ticket_id
  join public.compras c on c.id = en.compra_id
  where t.evento_id = p_evento_id
    and c.estado_pago = 'confirmado'
    and en.estado <> 'anulada';

  -- cada compra es de UN solo evento, así que sus cargos de servicio le pertenecen
  select coalesce(sum(c.cargos_servicio), 0)
    into v_servicios
  from public.compras c
  where c.estado_pago = 'confirmado'
    and exists (
      select 1
      from public.entradas en
      join public.tipos_ticket t on t.id = en.tipo_ticket_id
      where en.compra_id = c.id and t.evento_id = p_evento_id
    );

  return query select v_usuarios, v_entradas, v_subtotal, v_servicios, v_subtotal + v_servicios;
end;
$function$

CREATE OR REPLACE FUNCTION public.generar_lote_qr(p_evento integer, p_cantidad integer, p_solicitud uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_lote public.lotes_qr_fisico%rowtype;
begin
  if not public.qpass_autorizado_evento(p_evento, array[]::text[]) then
    raise exception 'SIN_PERMISOS' using errcode = '42501';
  end if;
  if p_cantidad is null or p_cantidad not between 1 and 200 or p_solicitud is null then
    raise exception 'DATOS_INVALIDOS' using errcode = '22023';
  end if;
  if not exists(select 1 from public.eventos where id=p_evento and tipo_acceso='qr_fisico') then
    raise exception 'EVENTO_NO_FISICO';
  end if;
  insert into public.lotes_qr_fisico(evento_id,cantidad,generado_por,solicitud_id)
  values(p_evento,p_cantidad,auth.uid(),p_solicitud) on conflict(solicitud_id) do nothing returning * into v_lote;
  if v_lote.id is null then
    select * into v_lote from public.lotes_qr_fisico where solicitud_id=p_solicitud;
    if v_lote.evento_id<>p_evento or v_lote.cantidad<>p_cantidad or v_lote.generado_por<>auth.uid() then
      raise exception 'SOLICITUD_REUTILIZADA';
    end if;
    return v_lote.id;
  end if;
  insert into public.vinculos_qr_fisico(lote_id,codigo_qr)
  select v_lote.id,'QPF-' || upper(replace(gen_random_uuid()::text,'-','')) from generate_series(1,p_cantidad);
  return v_lote.id;
end;
$function$

CREATE OR REPLACE FUNCTION public.guardar_evento_completo(p_evento_id integer, p_organizador_id uuid, p_estado estado_evento, p_datos jsonb, p_tickets jsonb)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
declare
  v_id integer;
  t    jsonb;
begin
  if p_evento_id is not null then
    perform id from public.eventos where id=p_evento_id for update;
    if not found then raise exception 'Evento no encontrado o sin permisos.'; end if;
    if not exists(select 1 from public.eventos where id=p_evento_id and version_edicion::text=p_datos->>'version_edicion') then
      raise exception 'El evento cambio mientras lo editabas. Recarga antes de guardar.';
    end if;
    perform id from public.tipos_ticket where evento_id=p_evento_id order by id for update;
    for t in select * from jsonb_array_elements(p_tickets) loop
      if t->>'id' is not null and not exists(select 1 from public.tipos_ticket where id=(t->>'id')::integer and evento_id=p_evento_id and version_edicion::text=t->>'version_edicion') then
        raise exception 'Los tickets o el cupo cambiaron mientras editabas. Recarga antes de guardar.';
      end if;
    end loop;
  end if;
  if p_evento_id is null then
    if p_organizador_id is null or p_estado is null then
      raise exception 'Faltan el organizador o el estado del evento.';
    end if;
    insert into eventos (organizador_id, categoria_id, titulo, descripcion, foto_url, ubicacion,
                         mapa_url, fecha_evento, fecha_fin, tipo_acceso, estado)
    values (p_organizador_id, nullif(p_datos->>'categoria_id','')::integer, p_datos->>'titulo',
            nullif(p_datos->>'descripcion',''), nullif(p_datos->>'foto_url',''), p_datos->>'ubicacion',
            nullif(p_datos->>'mapa_url',''), (p_datos->>'fecha_evento')::timestamptz,
            (p_datos->>'fecha_fin')::timestamptz, (p_datos->>'tipo_acceso')::tipo_acceso_evento, p_estado)
    returning id into v_id;
  else
    update eventos set
      categoria_id = nullif(p_datos->>'categoria_id','')::integer,
      titulo       = p_datos->>'titulo',
      descripcion  = nullif(p_datos->>'descripcion',''),
      foto_url     = nullif(p_datos->>'foto_url',''),
      ubicacion    = p_datos->>'ubicacion',
      mapa_url     = nullif(p_datos->>'mapa_url',''),
      fecha_evento = (p_datos->>'fecha_evento')::timestamptz,
      fecha_fin    = (p_datos->>'fecha_fin')::timestamptz,
      tipo_acceso  = (p_datos->>'tipo_acceso')::tipo_acceso_evento,
      estado       = coalesce(p_estado, estado)
    where id = p_evento_id
    returning id into v_id;
    if v_id is null then
      raise exception 'Evento no encontrado o sin permisos para editarlo.';
    end if;
  end if;

  -- quita los tickets que ya no vienen (si tienen ventas, la FK lo impide y todo se revierte)
  delete from tipos_ticket
  where evento_id = v_id
    and id not in (select (x->>'id')::integer from jsonb_array_elements(p_tickets) x where x->>'id' is not null);

  for t in select * from jsonb_array_elements(p_tickets) loop
    if t->>'id' is not null then
      update tipos_ticket set
        nombre = t->>'nombre',
        descripcion = nullif(t->>'descripcion',''),
        precio = (t->>'precio')::numeric,
        cantidad_disponible = (t->>'cantidad_disponible')::integer,
        limite_por_usuario = (t->>'limite_por_usuario')::integer
      where id = (t->>'id')::integer and evento_id = v_id;
    else
      insert into tipos_ticket (evento_id, nombre, descripcion, precio, cantidad_disponible, limite_por_usuario)
      values (v_id, t->>'nombre', nullif(t->>'descripcion',''), (t->>'precio')::numeric,
              (t->>'cantidad_disponible')::integer, (t->>'limite_por_usuario')::integer);
    end if;
  end loop;

  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.historial_accesos(p_evento integer, p_resultado text DEFAULT ''::text, p_fecha date DEFAULT NULL::date, p_incluir_eliminados boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_result jsonb;
begin
  if not public.qpass_autorizado_evento(p_evento,array['supervisor']) then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  if p_resultado not in ('','permitido','denegado') then raise exception 'DATOS_INVALIDOS'; end if;
  select coalesce(jsonb_agg(x order by x.registrado_en desc,x.id desc),'[]'::jsonb) into v_result from (
    select a.id,a.resultado,a.registrado_en,a.foto_url,a.observacion,a.eliminado,a.version,u.nombre,
      (select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'descripcion',r.descripcion,'estado',r.estado) order by r.creado_en desc),'[]'::jsonb)
       from public.reportes_acceso r where r.registro_acceso_id=a.id and r.usuario_id=auth.uid()) as reportes,
      (select coalesce(jsonb_agg(jsonb_build_object('motivo',au.motivo,'fecha',au.creado_en,'antes',au.antes->>'resultado','despues',au.despues->>'resultado') order by au.creado_en desc),'[]'::jsonb)
       from public.auditoria_accesos au where au.registro_id=a.id) as correcciones
    from public.registros_acceso a join public.entradas en on en.id=a.entrada_id join public.tipos_ticket t on t.id=en.tipo_ticket_id
    join public.usuarios u on u.id=en.usuario_destino_id where t.evento_id=p_evento
      and (a.supervisor_id=auth.uid() or public.qpass_autorizado_evento(null,array[]::text[]))
      and (p_incluir_eliminados or not a.eliminado) and (p_resultado='' or a.resultado::text=p_resultado)
      and (p_fecha is null or (a.registrado_en at time zone 'America/La_Paz')::date=p_fecha)
    order by a.registrado_en desc,a.id desc limit 100
  ) x;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.identificar_qr(p_codigo text, p_evento integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_id integer; v_origen text := 'digital'; v_result jsonb;
begin
  if not public.qpass_autorizado_evento(p_evento,array['supervisor','recargador','ayudante']) then
    raise exception 'SIN_PERMISOS' using errcode='42501';
  end if;
  if p_codigo is null or length(p_codigo)>255 or p_evento is null then raise exception 'DATOS_INVALIDOS' using errcode='22023'; end if;
  select id into v_id from public.entradas where codigo_qr=p_codigo;
  if v_id is null then
    v_origen := 'fisico';
    select v.entrada_id into v_id from public.vinculos_qr_fisico v join public.lotes_qr_fisico l on l.id=v.lote_id
      where v.codigo_qr=p_codigo and l.evento_id=p_evento;
  end if;
  select jsonb_build_object('entradaId',en.id,'usuarioId',u.id,'nombre',u.nombre,'eventoId',t.evento_id,
    'origen',v_origen,'estadoEntrada',en.estado,'pagoConfirmado',c.estado_pago='confirmado',
    'aptaIngreso',en.estado='activa' and c.estado_pago='confirmado' and u.activo,
    'identificacionValida',en.estado in ('activa','usada') and c.estado_pago='confirmado' and u.activo)
  into v_result from public.entradas en join public.tipos_ticket t on t.id=en.tipo_ticket_id
    join public.compras c on c.id=en.compra_id join public.usuarios u on u.id=en.usuario_destino_id
    where en.id=v_id and t.evento_id=p_evento;
  if v_result is null then raise exception 'QR_NO_VALIDO_PARA_EVENTO'; end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.proteger_campos_evento()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if (select auth.uid()) is null or public.es_admin() then
    return new;
  end if;

  if new.estado is distinct from old.estado then
    raise exception 'Solo un administrador puede cambiar el estado de un evento.' using errcode = '42501';
  end if;
  if new.organizador_id is distinct from old.organizador_id then
    raise exception 'No se puede cambiar el organizador de un evento.' using errcode = '42501';
  end if;
  if new.destacado_carrusel is distinct from old.destacado_carrusel then
    raise exception 'Solo un administrador puede destacar un evento en la landing.' using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.registrar_acceso(p_codigo text, p_evento integer, p_permitir boolean, p_foto text, p_solicitud uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_identidad jsonb; v_entrada public.entradas%rowtype; v_previo public.registros_acceso%rowtype; v_id integer;
begin
  if not public.qpass_autorizado_evento(p_evento,array['supervisor']) then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  if p_solicitud is null or p_permitir is null then raise exception 'DATOS_INVALIDOS'; end if;
  perform pg_advisory_xact_lock(hashtextextended(auth.uid()::text||':acceso:'||p_solicitud::text,0));
  select * into v_previo from public.registros_acceso where supervisor_id=auth.uid() and solicitud_id=p_solicitud;
  if found then
    if v_previo.codigo_leido is distinct from p_codigo or (v_previo.resultado='permitido')<>p_permitir or v_previo.foto_url is distinct from p_foto
      or not exists(select 1 from public.entradas en join public.tipos_ticket t on t.id=en.tipo_ticket_id where en.id=v_previo.entrada_id and t.evento_id=p_evento)
    then raise exception 'SOLICITUD_REUTILIZADA'; end if;
    return jsonb_build_object('id',v_previo.id,'resultado',v_previo.resultado,'repetido',true);
  end if;
  v_identidad:=public.identificar_qr(p_codigo,p_evento);
  if p_foto is null or split_part(p_foto,'/',1)<>auth.uid()::text or split_part(p_foto,'/',2)<>p_evento::text
    or not exists(select 1 from storage.objects where bucket_id='accesos' and name=p_foto) then raise exception 'FOTO_REQUERIDA'; end if;
  perform c.id from public.compras c join public.entradas en on en.compra_id=c.id where en.id=(v_identidad->>'entradaId')::integer for update of c;
  perform t.id from public.tipos_ticket t join public.entradas en on en.tipo_ticket_id=t.id where en.id=(v_identidad->>'entradaId')::integer for update of t;
  select * into v_entrada from public.entradas where id=(v_identidad->>'entradaId')::integer for update;
  -- Revalidar después de los bloqueos: una consulta anterior no autoriza el ingreso.
  v_identidad:=public.identificar_qr(p_codigo,p_evento);
  if p_permitir then
    if not (v_identidad->>'aptaIngreso')::boolean then raise exception 'ENTRADA_NO_APTA'; end if;
    update public.entradas set estado='usada' where id=v_entrada.id;
  end if;
  insert into public.registros_acceso(supervisor_id,entrada_id,resultado,foto_url,solicitud_id,codigo_leido)
    values(auth.uid(),v_entrada.id,case when p_permitir then 'permitido'::public.resultado_acceso else 'denegado'::public.resultado_acceso end,p_foto,p_solicitud,p_codigo) returning id into v_id;
  return jsonb_build_object('id',v_id,'resultado',case when p_permitir then 'permitido' else 'denegado' end,'repetido',false);
end;
$function$

CREATE OR REPLACE FUNCTION public.reportar_acceso(p_id integer, p_descripcion text, p_solicitud uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_evento integer; v_id integer; v_previo public.reportes_acceso%rowtype;
begin
  select t.evento_id into v_evento from public.registros_acceso a join public.entradas en on en.id=a.entrada_id
    join public.tipos_ticket t on t.id=en.tipo_ticket_id where a.id=p_id and a.supervisor_id=auth.uid();
  if not found or not public.qpass_autorizado_evento(v_evento,array['supervisor']) then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  if p_solicitud is null or length(btrim(coalesce(p_descripcion,''))) not between 5 and 2000 then raise exception 'DATOS_INVALIDOS'; end if;
  insert into public.reportes_acceso(registro_acceso_id,usuario_id,descripcion,solicitud_id)
    values(p_id,auth.uid(),btrim(p_descripcion),p_solicitud) on conflict(usuario_id,solicitud_id) do nothing returning id into v_id;
  if v_id is null then
    select * into v_previo from public.reportes_acceso where usuario_id=auth.uid() and solicitud_id=p_solicitud;
    if v_previo.registro_acceso_id<>p_id or v_previo.descripcion<>btrim(p_descripcion) then raise exception 'SOLICITUD_REUTILIZADA'; end if;
    return v_previo.id;
  end if;
  return v_id;
end;
$function$

CREATE OR REPLACE FUNCTION public.resolver_reporte_admin(p_tipo text, p_id integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_count integer;
begin
  if auth.uid() is null or not public.es_admin() then
    raise exception 'No tienes permisos de administrador.' using errcode = '42501';
  end if;
  if p_tipo = 'entrada' then
    update public.reportes_entrada set estado = 'solucionado' where id = p_id;
  elsif p_tipo = 'recarga' then
    update public.reportes_recarga set estado = 'solucionado' where id = p_id;
  elsif p_tipo = 'acceso' then
    update public.reportes_acceso set estado = 'solucionado' where id = p_id;
  else
    raise exception 'Tipo de reporte inválido.' using errcode = '22023';
  end if;
  get diagnostics v_count = row_count;
  return v_count = 1;
end;
$function$

CREATE OR REPLACE FUNCTION public.resumen_dashboard(p_evento integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_rol text; v_result jsonb;
begin
  select rol::text into v_rol from public.usuarios where id=auth.uid() and activo;
  if v_rol is null then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  if p_evento is null then
    if v_rol<>'admin' then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
    select jsonb_build_object(
      'entradas',(select count(*) from public.entradas en join public.compras c on c.id=en.compra_id where c.estado_pago='confirmado' and en.estado<>'anulada'),
      'compras',(select count(*) from public.compras where estado_pago='confirmado'),
      'ingresos',(select coalesce(sum(total),0) from public.compras where estado_pago='confirmado'),
      'usuarios',(select count(*) from public.usuarios),
      'eventos',(select count(*) from public.eventos where estado='publicado' and fecha_evento>=now()),
      'historial',(select coalesce(jsonb_agg(x order by x.creado_en desc),'[]'::jsonb) from
        (select id,total,creado_en from public.compras where estado_pago='confirmado' order by creado_en desc,id desc limit 10) x)
    ) into v_result;
  else
    if v_rol<>'organizador' or not exists(select 1 from public.eventos where id=p_evento and organizador_id=auth.uid()) then
      raise exception 'SIN_PERMISOS' using errcode='42501';
    end if;
    with entradas_evento as (
      select en.* from public.entradas en join public.tipos_ticket t on t.id=en.tipo_ticket_id
      join public.compras c on c.id=en.compra_id where t.evento_id=p_evento and c.estado_pago='confirmado' and en.estado<>'anulada'
    ), compras_evento as (
      select c.id,c.total,c.creado_en from public.compras c
      where c.id in (select compra_id from entradas_evento)
    )
    select jsonb_build_object('entradas',(select count(*) from entradas_evento),
      'compras',(select count(*) from compras_evento),
      'ingresos',(select coalesce(sum(total),0) from compras_evento),
      'usuarios',(select count(distinct usuario_destino_id) from entradas_evento),
      'eventos',1,
      'historial',(select coalesce(jsonb_agg(x order by x.creado_en desc),'[]'::jsonb) from
        (select * from compras_evento order by creado_en desc,id desc limit 10) x)) into v_result;
  end if;
  return v_result;
end;
$function$

CREATE OR REPLACE FUNCTION public.sincronizar_correo_usuario()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.email is distinct from old.email then
    update public.usuarios set correo = new.email where id = new.id;
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.usuarios_proteger_campos()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
begin
  if current_user not in ('authenticated', 'anon') or public.es_admin() then
    return new;
  end if;
  if new.id is distinct from old.id
     or new.rol is distinct from old.rol
     or new.activo is distinct from old.activo
     or new.correo is distinct from old.correo then
    raise exception 'Solo un administrador puede cambiar el rol, el estado o el correo.'
      using errcode = '42501';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.vincular_manilla(p_codigo text, p_entrada_codigo text, p_carnet text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_entrada public.entradas%rowtype; v_manilla public.vinculos_qr_fisico%rowtype; v_evento integer; v_lote_evento integer;
begin
  if not public.qpass_autorizado_evento(null,array[]::text[]) then raise exception 'SIN_PERMISOS' using errcode='42501'; end if;
  -- Orden común: compra -> ticket -> entrada -> manilla.
  perform c.id from public.compras c join public.entradas en on en.compra_id=c.id
    where en.codigo_qr=p_entrada_codigo for update of c;
  perform t.id from public.tipos_ticket t join public.entradas en on en.tipo_ticket_id=t.id
    where en.codigo_qr=p_entrada_codigo for update of t;
  select * into v_entrada from public.entradas where codigo_qr=p_entrada_codigo for update;
  if not found then raise exception 'ENTRADA_NO_ENCONTRADA'; end if;
  if v_entrada.estado<>'activa' or not exists(select 1 from public.compras where id=v_entrada.compra_id and estado_pago='confirmado') then
    raise exception 'ENTRADA_NO_VALIDA';
  end if;
  select t.evento_id into v_evento from public.tipos_ticket t join public.eventos e on e.id=t.evento_id
    where t.id=v_entrada.tipo_ticket_id and e.tipo_acceso='qr_fisico';
  if v_evento is null then raise exception 'EVENTO_NO_FISICO'; end if;
  if p_carnet is null or btrim(p_carnet)='' or not exists(select 1 from public.usuarios
    where id=v_entrada.usuario_destino_id and activo and carnet_identidad=btrim(p_carnet)) then
    raise exception 'IDENTIDAD_NO_COINCIDE';
  end if;
  select * into v_manilla from public.vinculos_qr_fisico where codigo_qr=p_codigo for update;
  if not found then raise exception 'MANILLA_NO_ENCONTRADA'; end if;
  select evento_id into v_lote_evento from public.lotes_qr_fisico where id=v_manilla.lote_id;
  if v_lote_evento<>v_evento then raise exception 'EVENTO_NO_COINCIDE'; end if;
  if v_manilla.entrada_id=v_entrada.id and v_manilla.usuario_id=v_entrada.usuario_destino_id then return v_entrada.id; end if;
  if v_manilla.entrada_id is not null or v_manilla.usuario_id is not null then raise exception 'MANILLA_YA_VINCULADA'; end if;
  if exists(select 1 from public.vinculos_qr_fisico where entrada_id=v_entrada.id) then raise exception 'ENTRADA_YA_VINCULADA'; end if;
  update public.vinculos_qr_fisico set entrada_id=v_entrada.id,usuario_id=v_entrada.usuario_destino_id,
    carnet_identidad=btrim(p_carnet),vinculado_en=now() where id=v_manilla.id;
  return v_entrada.id;
end;
$function$
